CREATE DATABASE IF NOT EXISTS gmarg CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gmarg;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('staff','client') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS staff_profiles (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,department VARCHAR(120),phone VARCHAR(30),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS client_profiles (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,phone VARCHAR(30),company_name VARCHAR(160),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inquiries (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(30),message TEXT NOT NULL,status ENUM('new','in_progress','completed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(user_id),INDEX(status));
